// Generated by Codex and not thoroughly checked for correctness.
func TestPracticeValidation(t *testing.T) {
	for _, testCase := range []struct {
		name, body string
		valid      bool
	}{
		{"missing values stay uninitialized", `{}`, true},
		{"all explicit nulls", `{"status":null,"help_used":null,"solved_on":null,"time_spent":null,"notes":null}`, true},
		{"not started", `{"status":"not_started"}`, true},
		{"attempted", `{"status":"attempted"}`, true},
		{"in progress", `{"status":"in_progress"}`, true},
		{"solved without inferred details", `{"status":"solved"}`, true},
		{"none is recorded help", `{"help_used":"none"}`, true},
		{"test case help before solving", `{"help_used":"test_case"}`, true},
		{"hint", `{"help_used":"hint"}`, true},
		{"editorial", `{"help_used":"editorial"}`, true},
		{"solution", `{"help_used":"solution"}`, true},
		{"leap day", `{"solved_on":"2024-02-29"}`, true},
		{"earliest date", `{"solved_on":"0001-01-01"}`, true},
		{"latest date", `{"solved_on":"9999-12-31"}`, true},
		{"zero active time", `{"time_spent":0}`, true},
		{"maximum active time", `{"time_spent":2147483647}`, true},
		{"maximum unicode notes", `{"notes":"` + strings.Repeat("界", 512) + `"}`, true},
		{"empty notes clear", `{"notes":""}`, true},
		{"whitespace notes preserved", `{"notes":" \n "}`, true},
		{"skipped rejected", `{"status":"skipped"}`, false},
		{"case sensitive status", `{"status":"Solved"}`, false},
		{"empty status rejected", `{"status":""}`, false},
		{"unknown help", `{"help_used":"video"}`, false},
		{"empty help", `{"help_used":""}`, false},
		{"invalid calendar date", `{"solved_on":"2025-02-29"}`, false},
		{"year zero", `{"solved_on":"0000-01-01"}`, false},
		{"noncanonical date", `{"solved_on":"2026-1-01"}`, false},
		{"timestamp is not a date", `{"solved_on":"2026-01-01T00:00:00Z"}`, false},
		{"negative active time", `{"time_spent":-1}`, false},
		{"integer overflow", `{"time_spent":2147483648}`, false},
		{"int64 overflow", `{"time_spent":9223372036854775808}`, false},
		{"fractional time", `{"time_spent":1.5}`, false},
		{"numeric string time", `{"time_spent":"5"}`, false},
		{"boolean time", `{"time_spent":true}`, false},
		{"overlong notes", `{"notes":"` + strings.Repeat("界", 513) + `"}`, false},
		{"NUL notes", `{"notes":"\u0000"}`, false},
		{"invalid UTF8", "{\"notes\":\"" + string([]byte{0xff}) + "\"}", false},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			var patch items.ItemPatch
			err := json.Unmarshal([]byte(testCase.body), &patch)
			if err == nil {
				err = patch.Normalize()
			}
			practice := patch.Values()
			if (err == nil) != testCase.valid {
				t.Fatalf("validation error = %v, valid = %t", err, testCase.valid)
			}
			if testCase.name == "empty notes clear" && practice.Notes != nil {
				t.Fatal("empty notes were not normalized to null")
			}
			if testCase.name == "solved without inferred details" && (practice.HelpUsed != nil || practice.SolvedOn != nil || practice.TimeSpent != nil) {
				t.Fatal("status inferred optional details")
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestItemPatchPresenceAndDirectValidation(t *testing.T) {
	var patch items.ItemPatch
	if !patch.Empty() {
		t.Fatal("zero patch should be empty")
	}
	if err := json.Unmarshal([]byte(`{"notes":null,"time_spent":0}`), &patch); err != nil {
		t.Fatal(err)
	}
	if patch.Empty() || !patch.Notes.Set || patch.Notes.Value != nil || !patch.TimeSpent.Set || *patch.TimeSpent.Value != 0 || patch.Status.Set {
		t.Fatalf("omitted/null/zero distinction lost: %+v", patch)
	}
	invalid := string([]byte{0xff})
	practice := items.Practice{Notes: &invalid}
	if err := practice.Normalize(); !errors.Is(err, items.ErrInvalidPractice) {
		t.Fatalf("direct validation error = %v", err)
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestItemPatchIgnoresUnsetValues(t *testing.T) {
	invalidStatus := items.PracticeStatus("skipped")
	invalidHelp := items.PracticeHelp("unknown")
	invalidDate := "not-a-date"
	invalidTime := int64(-1)
	invalidNotes := strings.Repeat("界", 513)
	patch := items.ItemPatch{
		Status:    items.Field[items.PracticeStatus]{Value: &invalidStatus},
		HelpUsed:  items.Field[items.PracticeHelp]{Value: &invalidHelp},
		SolvedOn:  items.Field[string]{Value: &invalidDate},
		TimeSpent: items.Field[int64]{Value: &invalidTime},
		Notes:     items.Field[string]{Value: &invalidNotes},
	}
	if err := patch.Normalize(); err != nil || !patch.Empty() || !reflect.DeepEqual(patch.Values(), items.Practice{}) {
		t.Fatalf("unset values affected validation: %+v, error = %v", patch, err)
	}
	patch.Notes = items.Field[string]{Set: true, Value: &invalidNotes}
	if err := patch.Normalize(); !errors.Is(err, items.ErrInvalidPractice) {
		t.Fatalf("supplied invalid notes were accepted: %v", err)
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestPracticeValidationRunsBeforeDatabaseAccess(t *testing.T) {
	repository := items.NewRepository(nil, time.Second)
	invalidStatus := items.PracticeStatus("skipped")
	if err := repository.Create(t.Context(), 1, &items.ListItem{Practice: items.Practice{Status: &invalidStatus}}); !errors.Is(err, items.ErrInvalidPractice) {
		t.Fatal(err)
	}
	if _, err := repository.Update(t.Context(), 1, 1, "1900A", items.ItemPatch{}); !errors.Is(err, items.ErrInvalidPractice) {
		t.Fatal(err)
	}
	patch := items.ItemPatch{Status: items.Field[items.PracticeStatus]{Set: true, Value: &invalidStatus}}
	if _, err := repository.Update(t.Context(), 1, 1, "1900A", patch); !errors.Is(err, items.ErrInvalidPractice) {
		t.Fatal(err)
	}
}
